# Lot 2 : trois étapes, création en un écran, fenêtre de mise en page au premier passage, Publication.
from playwright.sync_api import sync_playwright
import serveur, json; _srv = serveur.demarrer()
res = []
def verifie(nom, cond, detail=''):
    res.append((nom, bool(cond))); print(('OK   ' if cond else 'ÉCHEC'), nom, detail if not cond else '')
src = open(serveur.DONNEES + '/rendre.py', encoding='utf-8').read()
P0 = eval(src[src.index('P0 = [') + 5: src.index(']', src.index('P0 = [')) + 1])
TEXTE = '\n\n'.join(P0)
plans = json.load(open(serveur.DONNEES + '/plans6.json', encoding='utf-8'))
BONS = [{'nom': p['nom'], 'pourquoi': p['pourquoi'], 'fond': p['fond'], 'slides': [{'gabarit': x['g'], 'paragraphes': x['p'], 'styles': x['s']} for x in p['pages']]} for p in plans]
CORS = {'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'content-type': 'application/json'}
envois = []
def claude(route):
    r = route.request
    if r.method == 'OPTIONS': return route.fulfill(status=204, headers=CORS)
    c = json.loads(r.post_data); envois.append(c)
    return route.fulfill(status=200, headers=CORS, body=json.dumps({'content': [{'type': 'tool_use', 'id': 't', 'name': c['tools'][0]['name'], 'input': {'reponse': 'Voici.', 'propositions': BONS}}], 'stop_reason': 'tool_use'}))
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={'width': 1180, 'height': 820})
    erreurs = []; pg.on('pageerror', lambda e: erreurs.append(str(e)))
    pg.route('https://api.anthropic.com/**', claude)
    pg.goto('http://localhost:8765/'); pg.wait_for_timeout(600)
    pg.evaluate("localStorage.setItem('postsop-ia', JSON.stringify({fournisseur:'claude', cles:{claude:'sk-ant-test'}, modeles:{}}))")
    pg.reload(); pg.wait_for_timeout(900)
    # Ancien article : pas d'ouverture automatique
    pg.get_by_text('Le silence au travail').first.click(); pg.wait_for_timeout(400)
    noms = pg.locator('nav.etapes .etape').all_inner_texts()
    verifie('trois étapes : Texte, Mise en page, Publication', [n.strip()[-12:].strip() for n in noms] == ['Texte', 'Mise en page', 'Publication'] or [n.split('\n')[-1].strip() for n in noms] == ['Texte', 'Mise en page', 'Publication'], noms)
    pg.get_by_role('button', name='Continuer : Mise en page').click(); pg.wait_for_timeout(500)
    verifie('article existant : la fenêtre ne s’ouvre pas toute seule', pg.get_by_role('dialog').count() == 0)
    pg.get_by_role('button', name='Articles').first.click(); pg.wait_for_timeout(300)
    # Création en un écran
    pg.get_by_role('button', name='Nouvel article').first.click(); pg.wait_for_timeout(300)
    fe = pg.locator('[role=dialog]').first
    verifie('création : plus de fenêtre, écran vierge', pg.get_by_role('dialog').count() == 0 and pg.locator('#texte-modele').count() == 1)
    pg.locator('#texte-modele').click(); pg.keyboard.insert_text(TEXTE); pg.wait_for_timeout(300)
    pg.get_by_role('button', name='Continuer', exact=True).click(); pg.wait_for_timeout(300); _q = pg.get_by_role('dialog', name='Ton nouvel article'); _q.get_by_role('button', name='Portrait · 4:5').click(); _q.get_by_role('button', name='Commencer').click(); pg.wait_for_timeout(700)
    verifie('après la création : étape Texte, aucun appel à CCB', pg.locator('.etape.active').inner_text().strip().endswith('Texte') and len(envois) == 0)
    verifie('étape Texte : plus de « Nouveau texte » ni de « Mise en page »', pg.get_by_role('button', name='Nouveau texte').count() == 0 and pg.get_by_role('button', name='Apparence générale', exact=True).count() == 0)
    # Premier passage : la fenêtre s'ouvre et CCB compose
    pg.get_by_role('button', name='Continuer : Mise en page').click(); pg.wait_for_timeout(1300)
    fw = pg.get_by_role('dialog', name='Choisis ta mise en page')
    verifie('premier passage : la fenêtre s’ouvre toute seule', fw.count() == 1)
    verifie('CCB compose sur le texte (un appel)', len(envois) == 1)
    seg = fw.get_by_role('group', name='Mises en page proposées')
    verifie('pas d’« Actuelle » au premier passage', seg.get_by_role('button', name='Actuelle').count() == 0 and seg.get_by_role('button').count() == 4, seg.get_by_role('button').all_inner_texts())
    fw.get_by_role('button', name='Garder dans mes favoris', exact=True).click(); pg.wait_for_timeout(150)
    seg.get_by_role('button', name=plans[1]['nom']).click(); pg.wait_for_timeout(200)
    fw.get_by_role('button', name='Appliquer').click(); pg.wait_for_timeout(700)
    verifie('appliqué : fenêtre fermée, 6 pages', pg.get_by_role('dialog').count() == 0 and pg.locator('.calque').count() == 6, pg.locator('.calque').count())
    # Second passage : rien ne s'ouvre ; le bouton « Mise en page… » rouvre la fenêtre
    pg.locator('nav.etapes .etape').nth(0).click(); pg.wait_for_timeout(300)
    pg.locator('nav.etapes .etape').nth(1).click(); pg.wait_for_timeout(500)
    verifie('second passage : la fenêtre ne se rouvre pas', pg.get_by_role('dialog').count() == 0)
    menu_carrousel = None
    pg.locator('.menus-composition .titre-menu').filter(has_text='Carrousel').first.click(); pg.wait_for_timeout(200)
    items = pg.locator('.popover-menu').first.inner_text()
    verifie('menu Carrousel sans redécoupage ni présentation au hasard ni « Mise en page et réglages »', 'Redécouper' not in items and 'autre présentation' not in items and 'Mise en page et réglages' not in items and 'Dimensions' in items, items)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
    pg.get_by_role('button', name='Apparence générale').first.click(); pg.wait_for_timeout(400)
    fr = pg.get_by_role('dialog', name='Apparence générale', exact=True)
    seg2 = fr.get_by_role('group', name='Mises en page proposées')
    verifie('« Mise en page… » : fenêtre sur « Actuelle », sans appel', fr.count() == 1 and seg2.get_by_role('button', name='Actuelle').get_attribute('aria-pressed') == 'true' and len(envois) == 1)
    verifie('un seul écran : mise en page, puis fond, logo et fleurs', fr.locator('.etapes-assistant').count() == 0 and 'Fond, logo et fleurs' in fr.inner_text() and fr.get_by_role('button', name='Appliquer').count() == 1)
    verifie('ni texte, ni réseau, ni dimensions dans la fenêtre', fr.locator('#texte-modele').count() == 0 and 'Réseau' not in fr.inner_text() and 'Dimensions' not in fr.inner_text())
    # Favoris
    fr.get_by_role('button', name='Mes favoris', exact=True).click(); pg.wait_for_timeout(200)
    fr.get_by_role('group', name='Mes carrousels favoris').get_by_role('button', name='Choisir «').first.click(); pg.wait_for_timeout(300)
    verifie('favori appliqué à ce texte', seg2.get_by_role('button', name='★ ' + plans[0]['nom']).get_attribute('aria-pressed') == 'true' and 'Favori' in fr.locator('.mep-infos').inner_text(), fr.locator('.mep-infos').inner_text()[:120])
    # Sans IA, au hasard
    seg2.get_by_role('button', name='Sans IA').click(); pg.wait_for_timeout(200)
    fr.get_by_role('button', name='Une autre au hasard').click(); pg.wait_for_timeout(300)
    verifie('« Une autre au hasard » sous Sans IA', 'Sans IA, au hasard' in fr.locator('.mep-infos').inner_text())
    fr.locator('.feuille-tete').get_by_role('button', name='Annuler').click(); pg.wait_for_timeout(200)
    # Menu CCB : « Mise en page… »
    pg.locator('.bouton-robot-menu').click(); pg.wait_for_timeout(200)
    n_av = len(envois)
    pg.get_by_role('menuitem', name='Générer 3 propositions').click(); pg.wait_for_timeout(1300)
    fg = pg.get_by_role('dialog', name='Apparence générale', exact=True)
    sg = fg.get_by_role('group', name='Mises en page proposées')
    verifie('robot › « Générer 3 propositions » : la fenêtre s’ouvre et CCB compose aussitôt', fg.count() == 1 and len(envois) == n_av + 1 and sg.get_by_role('button', name='Actuelle').count() == 1 and sg.get_by_role('button').count() >= 4, (len(envois) - n_av, sg.get_by_role('button').all_inner_texts() if fg.count() else []))
    pg.get_by_role('dialog', name='Apparence générale', exact=True).locator('.feuille-tete').get_by_role('button', name='Annuler').click(); pg.wait_for_timeout(200)
    # Publication
    pg.get_by_role('button', name='Continuer : Publication').click(); pg.wait_for_timeout(500)
    corps = pg.locator('main').inner_text()
    verifie('Publication : quatre temps numérotés', all(t in corps for t in ['1 · Texte du post LinkedIn', '2 · Fichier', '3 · Date de publication', '4 · Publié ?']), corps[:300])
    pg.get_by_role('group', name='Réseau du texte').get_by_role('button', name='Instagram').click() if pg.get_by_role('group', name='Réseau du texte').count() else pg.locator('.publication-reseau').get_by_role('button', name='Instagram').click()
    pg.wait_for_timeout(200)
    verifie('texte pour Instagram', '1 · Légende Instagram' in pg.locator('main').inner_text())
    prog = pg.locator('.carte').filter(has_text='Date de publication')
    verifie('par défaut : « Ne pas programmer »', prog.get_by_role('button', name='Ne pas programmer').get_attribute('aria-pressed') == 'true' and prog.locator('input[type=date]').count() == 0)
    prog.get_by_role('button', name='Programmer', exact=True).click(); pg.wait_for_timeout(300)
    verifie('« Programmer » : date et heure', prog.locator('input[type=date]').count() == 1 and prog.locator('input[type=time]').input_value() == '09:00')
    prog.get_by_role('button', name='Ouvrir le calendrier').click(); pg.wait_for_timeout(300)
    verifie('le calendrier s’ouvre depuis l’article', pg.get_by_role('dialog').count() == 1)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
    prog.get_by_role('button', name='Ne pas programmer').click(); pg.wait_for_timeout(300)
    verifie('« Ne pas programmer » retire la date', prog.locator('input[type=date]').count() == 0 and 'non programmée' in (pg.locator('.message').inner_text() if pg.locator('.message').count() else ''))
    pg.evaluate('window.scrollTo(0, 0)'); pg.wait_for_timeout(150); pg.locator('.publication-apercu .page-cliquable').click(); pg.wait_for_timeout(300)
    pg.locator('.grande-fenetre').get_by_role('button', name='Aperçu du post Instagram').click(); pg.wait_for_timeout(200)
    verifie('aperçu du post Instagram depuis Publication', pg.get_by_role('dialog', name='Aperçu du post').count() == 1 and 'Instagram' in pg.get_by_role('dialog', name='Aperçu du post').inner_text())
    pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
    verifie('Échap ferme l’aperçu puis la grande fenêtre', pg.locator('.grande-fenetre').count() == 0)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
    pg.get_by_role('button', name='Marquer comme publié').click(); pg.wait_for_timeout(300)
    verifie('marquer comme publié', 'Publié le' in pg.locator('main').inner_text())
    pg.screenshot(path='lot2-publication.png', full_page=True)
    verifie('dernière étape : « Terminer »', pg.get_by_role('button', name='Terminer').count() == 1)
    # Aide « i » à l'étape Mise en page : au-dessus de la barre de menus
    pg.locator('nav.etapes .etape').nth(1).click(); pg.wait_for_timeout(400)
    pg.locator('header button', has_text='i').last.click() if pg.locator('header button', has_text='i').count() else pg.get_by_role('button', name='i', exact=True).click()
    pg.wait_for_timeout(300)
    za = pg.locator('.panneau-aide').evaluate("e => [Number(getComputedStyle(e).zIndex), Number(getComputedStyle(document.querySelector('.menus-composition')).zIndex), (() => { const r = e.getBoundingClientRect(); const m = document.querySelector('.menus-composition').getBoundingClientRect(); const x = r.left + 40, y = m.top + m.height / 2; const el = document.elementFromPoint(x, y); return !!(el && el.closest('.panneau-aide')); })()]") if pg.locator('.panneau-aide').count() else [0, 0, False]
    verifie('l’aide passe au-dessus de la barre de menus', za[0] > za[1] and za[2], za)
    verifie('aucune erreur JS', not erreurs, erreurs)
    b.close()
print(sum(1 for _, o in res if o), '/', len(res), 'vérifications réussies')
